import React from 'react';

// Приймаємо функцію setSort як пропс
const Filters = ({ setSort }) => {
    
    // Функція, яка спрацьовує при виборі в селекті
    const handleSortChange = (e) => {
        setSort(e.target.value);
    };

    return (
        <aside className="sidebar">
            <div className="filter-group">
                <h3>Search</h3>
                <input type="text" placeholder="Type to search..." className="search-input" />
            </div>
            
            <div className="filter-group">
                <h3>Sort by</h3>
                {/* Додали onChange */}
                <select className="sort-select" onChange={handleSortChange}>
                    <option value="default">Default</option>
                    <option value="price_asc">Price (Low to High)</option>
                    <option value="price_desc">Price (High to Low)</option>
                    <option value="rating">Rating (Best first)</option>
                </select>
            </div>
        </aside>
    );
};

export default Filters;
